store = {}

def save(collection, doc_id, doc):
    store.setdefault(collection, {})[doc_id] = doc

def find(collection, key, value):
    return [d for d in store.get(collection, {}).values()
            if d.get(key) == value]

save("users", "u1", {"name": "Alice", "role": "admin"})
save("users", "u2", {"name": "Bob",   "role": "user"})
save("users", "u3", {"name": "Carol", "role": "admin"})

for u in find("users", "role", "admin"):
    print(u["name"])
